import{_ as a,o as e,c as s,a5 as d}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"13. 运算符和表达式","description":"The Little Book of C 中文版 — 13. 运算符和表达式","frontmatter":{"title":"13. 运算符和表达式","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","02-语言基础","中文"],"description":"The Little Book of C 中文版 — 13. 运算符和表达式","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":13,"sidebarWeight":13,"alternateZh":"/posts/c教程/zh-CN/02-语言基础/013-Operators and Expressions","alternateEn":"/posts/c教程/en-US/02-Language Basics/013-Operators and Expressions"},"headers":[],"relativePath":"posts/c教程/zh-CN/02-语言基础/013-Operators and Expressions.md","filePath":"posts/c教程/zh-CN/02-语言基础/013-Operators and Expressions.md","lastUpdated":1790163617000}'),n={name:"posts/c教程/zh-CN/02-语言基础/013-Operators and Expressions.md"};function o(i,t,p,c,l,r){return e(),s("div",null,[...t[0]||(t[0]=[d(`<p>[English version](/posts/c教程/en-US/02-Language Basics/013-Operators and Expressions)</p><p>运算符是 C 中计算的构建块。它们使您可以用简洁的表达式执行算术、比较值、操作位和组合逻辑。一旦您了解了运算符的工作原理以及它们如何通过优先级和关联性进行交互，您就可以编写出清晰、高效的代码，其行为完全符合您的预期。</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int a = 10, b = 3;</span></span>
<span class="line"><span>    printf(&quot;a + b = %d\\n&quot;, a + b);   // addition</span></span>
<span class="line"><span>    printf(&quot;a - b = %d\\n&quot;, a - b);   // subtraction</span></span>
<span class="line"><span>    printf(&quot;a * b = %d\\n&quot;, a * b);   // multiplication</span></span>
<span class="line"><span>    printf(&quot;a / b = %d\\n&quot;, a / b);   // integer division</span></span>
<span class="line"><span>    printf(&quot;a %% b = %d\\n&quot;, a % b);  // remainder (modulo)</span></span>
<span class="line"><span>    a += 5; // same as a = a + 5</span></span>
<span class="line"><span>    printf(&quot;a after += 5: %d\\n&quot;, a);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a + b = 13</span></span>
<span class="line"><span>a - b = 7</span></span>
<span class="line"><span>a * b = 30</span></span>
<span class="line"><span>a / b = 3</span></span>
<span class="line"><span>a % b = 1</span></span>
<span class="line"><span>a after += 5: 15</span></span></code></pre></div><h4 id="算术运算符" tabindex="-1">算术运算符 <a class="header-anchor" href="#算术运算符" aria-label="Permalink to &quot;算术运算符&quot;">​</a></h4><table tabindex="0"><thead><tr><th>操作员</th><th>意义</th><th>示例</th><th>结果</th></tr></thead><tbody><tr><td><code>+</code></td><td>加法</td><td><code>4 + 3</code></td><td>7</td></tr><tr><td><code>-</code></td><td>减法</td><td><code>10 - 6</code></td><td>4</td></tr><tr><td><code>*</code></td><td>乘法</td><td><code>2 * 5</code></td><td>10</td></tr><tr><td><code>/</code></td><td>事业部</td><td><code>7 / 2</code></td><td>3（整数除法）</td></tr><tr><td><code>%</code></td><td>模（余数）</td><td><code>7 % 2</code></td><td>1</td></tr></tbody></table><p>提示：如果您使用浮点数（<code>float</code>,<code>double</code>)，除法产生小数。</p><h4 id="关系运算符和逻辑运算符" tabindex="-1">关系运算符和逻辑运算符 <a class="header-anchor" href="#关系运算符和逻辑运算符" aria-label="Permalink to &quot;关系运算符和逻辑运算符&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类型</th><th>操作员</th><th>示例</th><th>意义</th></tr></thead><tbody><tr><td>关系</td><td><code>==</code></td><td><code>a == b</code></td><td>平等</td></tr><tr><td><code>!=</code></td><td><code>a != b</code></td><td>不等于</td><td></td></tr><tr><td><code>&lt;</code>,<code>&gt;</code>,<code>&lt;=</code>,<code>&gt;=</code></td><td><code>a &lt; b</code></td><td>比较</td><td></td></tr><tr><td>逻辑</td><td><code>&amp;&amp;</code></td><td><code>a &amp;&amp; b</code></td><td>逻辑与</td></tr><tr><td>\`</td><td></td><td>\`</td><td>\`a</td></tr><tr><td><code>!</code></td><td><code>!a</code></td><td>逻辑非</td><td></td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int age = 20;</span></span>
<span class="line"><span>if (age &gt;= 18 &amp;&amp; age &lt;= 60)</span></span>
<span class="line"><span>    printf(&quot;Adult\\n&quot;);</span></span></code></pre></div><h4 id="递增和递减" tabindex="-1">递增和递减 <a class="header-anchor" href="#递增和递减" aria-label="Permalink to &quot;递增和递减&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 5;</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, ++x); // prefix: increments, then uses value (6)</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, x++); // postfix: uses value, then increments (6)</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, x);   // final value is 7</span></span></code></pre></div><h4 id="赋值和复合运算符" tabindex="-1">赋值和复合运算符 <a class="header-anchor" href="#赋值和复合运算符" aria-label="Permalink to &quot;赋值和复合运算符&quot;">​</a></h4><table tabindex="0"><thead><tr><th>操作员</th><th>意义</th><th>示例</th></tr></thead><tbody><tr><td><code>=</code></td><td>作业</td><td><code>x = 10</code></td></tr><tr><td><code>+=</code></td><td>添加和分配</td><td><code>x += 2</code></td></tr><tr><td><code>-=</code></td><td>减法和赋值</td><td><code>x -= 3</code></td></tr><tr><td><code>*=</code></td><td>乘法和赋值</td><td><code>x *= 4</code></td></tr><tr><td><code>/=</code></td><td>划分和分配</td><td><code>x /= 5</code></td></tr><tr><td><code>%=</code></td><td>取模并赋值</td><td><code>x %= 6</code></td></tr></tbody></table><p>这些可以节省打字并使意图更清晰。</p><h4 id="按位运算符" tabindex="-1">按位运算符 <a class="header-anchor" href="#按位运算符" aria-label="Permalink to &quot;按位运算符&quot;">​</a></h4><p>C gives you direct access to bits, useful for systems, embedded, or optimization tasks.</p><table tabindex="0"><thead><tr><th>操作员</th><th>意义</th><th>示例</th></tr></thead><tbody><tr><td><code>&amp;</code></td><td>AND</td><td><code>a &amp; b</code></td></tr><tr><td>\`</td><td>\`</td><td>OR</td></tr><tr><td><code>^</code></td><td>XOR</td><td><code>a ^ b</code></td></tr><tr><td><code>~</code></td><td>NOT</td><td><code>~a</code></td></tr><tr><td><code>&lt;&lt;</code></td><td>Left shift</td><td><code>a &lt;&lt; 1</code></td></tr><tr><td><code>&gt;&gt;</code></td><td>Right shift</td><td><code>a &gt;&gt; 2</code></td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int mask = 0b0010;</span></span>
<span class="line"><span>int num = 0b1011;</span></span>
<span class="line"><span>int result = num &amp; mask;  // checks if the 2nd bit is set</span></span></code></pre></div><h4 id="precedence-and-associativity" tabindex="-1">Precedence and Associativity <a class="header-anchor" href="#precedence-and-associativity" aria-label="Permalink to &quot;Precedence and Associativity&quot;">​</a></h4><p>When you write complex expressions, C follows operator precedence rules. For example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int result = 2 + 3 * 4; // result is 14, not 20</span></span></code></pre></div><p><code>*</code>has higher precedence than<code>+</code>, so it runs first.</p><p>Use parentheses to make intentions clear:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int result = (2 + 3) * 4; // result is 20</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Operators are where logic meets the machine. They translate mathematical ideas and control decisions into instructions the CPU executes directly. Understanding how expressions are built and evaluated helps you:</p><ul><li>Write compact, efficient code</li><li>Avoid precedence mistakes</li><li>Control exactly what your program computes</li></ul><p>In low-level work (like bitwise operations or embedded systems), operator mastery is essential.</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>Write a small program that takes two integers and prints their:</p><ul><li>总和</li><li>差异</li><li>产品</li><li>商数</li><li>余数</li></ul><p>Modify it to print results as floating-point values.</p><p>使用逻辑运算符来测试两个数字是否为正数。</p><p>Try combining bitwise operations:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;%d\\n&quot;, 5 &amp; 3);  // AND</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, 5 | 3);  // OR</span></span>
<span class="line"><span>printf(&quot;%d\\n&quot;, 5 ^ 3);  // XOR</span></span></code></pre></div><p>Experiment with parentheses and operator order until you can predict every result.</p><p>运算符是 C 的简单性与强大功能的结合，是一小组符号，可让您完全控制计算、逻辑甚至原始位。</p>`,42)])])}const b=a(n,[["render",o]]);export{u as __pageData,b as default};
